 public sealed class RepairRuntimeQa:MonoBehaviour {
  RepairGame game;string output,mode;int passes,errors;readonly List<float> frames=new();
  [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void StartQa(){if(!string.IsNullOrEmpty(Environment.GetEnvironmentVariable("REPAIR_QA_MODE")))new GameObject("RepairRuntimeQA").AddComponent<RepairRuntimeQa>();}
  void Awake(){mode=Environment.GetEnvironmentVariable("REPAIR_QA_MODE");output=Environment.GetEnvironmentVariable("REPAIR_QA_OUTPUT")??Path.Combine(Application.persistentDataPath,"RepairQA");Directory.CreateDirectory(output);Application.logMessageReceived+=Log;Application.runInBackground=true;}
  void Log(string text,string stack,LogType type){if(type==LogType.Error||type==LogType.Exception||type==LogType.Assert){errors++;File.AppendAllText(Path.Combine(output,"errors.txt"),text+"\n"+stack+"\n");}}
  void Check(bool value,string title){if(!value)throw new Exception("REPAIR_QA_FAIL "+title);passes++;Debug.Log("REPAIR_QA_PASS "+title);File.AppendAllText(Path.Combine(output,"checks.txt"),title+"\n");}
  IEnumerator Start(){yield return new WaitForSecondsRealtime(2);game=FindFirstObjectByType<RepairGame>();var routine=Run();while(true){bool next;try{next=routine.MoveNext();}catch(Exception e){Debug.LogException(e);File.WriteAllText(Path.Combine(output,"FAIL.txt"),e.ToString());yield break;}if(!next)break;yield return routine.Current;}}
  IEnumerator Capture(string name){yield return new WaitForEndOfFrame();var image=ScreenCapture.CaptureScreenshotAsTexture();try{File.WriteAllBytes(Path.Combine(output,name+".png"),image.EncodeToPNG());}finally{Destroy(image);}yield return null;}
  HoldButton FindHold(string name)=>GameObject.Find(name)?.GetComponent<HoldButton>();
  void Held(HoldButton hold,bool value){Check(hold!=null,"Actual hold exists "+(hold!=null?hold.name:"missing"));if(value)ExecuteEvents.Execute(hold.gameObject,new PointerEventData(EventSystem.current),ExecuteEvents.pointerDownHandler);else ExecuteEvents.Execute(hold.gameObject,new PointerEventData(EventSystem.current),ExecuteEvents.pointerUpHandler);}
  void SetHeld(HoldButton hold,bool value){if(hold.Held==value)return;if(value)hold.OnPointerDown(new PointerEventData(EventSystem.current));else hold.OnPointerUp(new PointerEventData(EventSystem.current));}
  void Press(string name){var go=GameObject.Find(name);Check(go!=null,"Actual UI exists "+name);var button=go.GetComponent<Button>();Check(button!=null&&button.interactable,"Actual UI enabled "+name);var point=UiMetrics.ScreenRect((RectTransform)go.transform).center;var hits=new List<RaycastResult>();EventSystem.current.RaycastAll(new PointerEventData(EventSystem.current){position=point},hits);Check(hits.Count>0&&(hits[0].gameObject==go||hits[0].gameObject.transform.IsChildOf(go.transform)),"Actual touch raycast "+name);ExecuteEvents.Execute(go,new PointerEventData(EventSystem.current){position=point},ExecuteEvents.pointerClickHandler);}
  void Sizes(){Canvas.ForceUpdateCanvases();float scale=UiMetrics.PointScale;foreach(var b in game.Hud.GetComponentsInChildren<Selectable>()){if(!b.gameObject.activeInHierarchy)continue;var r=UiMetrics.ScreenRect((RectTransform)b.transform);Check(r.width/scale>=47.999f&&r.height/scale>=47.999f,"48 point target "+b.name);}foreach(var photo in game.Hud.GetComponentsInChildren<RawImage>()){if(!photo.gameObject.activeInHierarchy||photo.name!="ServicePhoto")continue;var shape=photo.rectTransform.rect;float sampledAspect=photo.uvRect.width*photo.texture.width/(photo.uvRect.height*photo.texture.height);Check(Mathf.Abs(sampledAspect-shape.width/shape.height)<.001f,"Actual service photo preserves authored proportions "+photo.name);}int driving=0;foreach(var hold in game.Hud.GetComponentsInChildren<HoldButton>()){if(!hold.gameObject.activeInHierarchy)continue;var r=UiMetrics.ScreenRect((RectTransform)hold.transform);Check(r.width/scale>=47.999f&&r.height/scale>=47.999f,"48 point held target "+hold.name);if(hold==game.Vehicle.Left||hold==game.Vehicle.Right||hold==game.Vehicle.Brake||hold==game.Vehicle.Accelerate){driving++;Rect view=UnityEngine.Camera.main.pixelRect;Check(view.Contains(r.min+Vector2.one)&&view.Contains(r.max-Vector2.one),"Hold control inside usable region "+hold.name);}}if(!game.Hud.ModalOpen)Check(driving==4,"Four actual driving controls validated");}
