   game.Hud.ShowPage(7);var apply=typeof(RepairHud).GetMethod("ApplyShopAvailability",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance);Check(apply!=null,"Timed shop eligibility updates actual controls");apply.Invoke(game.Hud,new object[]{false,false,false,false});Check(!GameObject.Find("RetryAction").GetComponent<Button>().interactable,"Shop retry disabled before deadline");var gate=new Kamilunavo.RepairEmpire.Monetization.StoreReconnectGate();gate.Failed(0);apply.Invoke(game.Hud,new object[]{false,gate.CanBegin(5),false,false});Check(GameObject.Find("RetryAction").GetComponent<Button>().interactable,"Expired retry enables without navigating");apply.Invoke(game.Hud,new object[]{true,true,false,false});Check(GameObject.Find("RewardVideoAction").GetComponent<Button>().interactable,"Replacement video eligibility refreshes without navigating");
   var tick=typeof(Kamilunavo.RepairEmpire.Monetization.RewardedVideos).GetMethod("TickPreparation",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance);Check(tick!=null,"Replacement preparation scheduled while shop stays open");var retryField=typeof(Kamilunavo.RepairEmpire.Monetization.RewardedVideos).GetField("_retryAt",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance);retryField.SetValue(game.Videos,20d);int loads=0;Action load=()=>loads++;tick.Invoke(game.Videos,new object[]{19d,load});Check(loads==0,"Video replacement waits for retry deadline");tick.Invoke(game.Videos,new object[]{20d,load});Check(loads==1,"Video replacement prepared after retry deadline");tick.Invoke(game.Videos,new object[]{20.5d,load});Check(loads==1,"Video preparation polling is throttled");retryField.SetValue(game.Videos,0d);
   var restore=typeof(Kamilunavo.RepairEmpire.Monetization.StorePurchases).GetMethod("RestoreCore",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance);Check(restore!=null,"Restore owns native presentation");Action<bool,string> complete=null;Action<Action<bool,string>> delayed=callback=>complete=callback;restore.Invoke(game.Store,new object[]{delayed});Check(game.Store.Busy&&game.Store.IsPresenting,"Pending restore reserves pause");var fetched=typeof(Kamilunavo.RepairEmpire.Monetization.StorePurchases).GetMethod("PurchasesFailed",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance);fetched.Invoke(game.Store,new object[]{null});Check(game.Store.IsPresenting,"Purchase refresh cannot release pending restore ownership");game.Hud.Close();Check(game.Hud.ShopOpen&&game.Paused,"Close blocked during pending restore");var consent=typeof(Kamilunavo.RepairEmpire.Monetization.RewardedVideos).GetMethod("TryPresentConsent",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance);bool shown=false;Check(!(bool)consent.Invoke(game.Videos,new object[]{(Action)(()=>shown=true)})&&!shown,"Delayed consent cannot overlap restore");complete(false,"offline");Check(!game.Store.Busy&&!game.Store.IsPresenting,"Restore failure releases pause");restore.Invoke(game.Store,new object[]{(Action<Action<bool,string>>)(callback=>callback(true,""))});Check(!game.Store.Busy&&!game.Store.IsPresenting,"Restore success releases pause");restore.Invoke(game.Store,new object[]{(Action<Action<bool,string>>)(callback=>throw new Exception("start failed"))});Check(!game.Store.Busy&&!game.Store.IsPresenting,"Restore exception releases pause");game.Hud.Close();
   Sizes();var left=game.Vehicle.Left;var rect=(RectTransform)left.transform;var saved=rect.anchoredPosition;rect.anchoredPosition+=new Vector2(-5000,0);bool rejected=false;try{Sizes();}catch{rejected=true;}rect.anchoredPosition=saved;Check(rejected,"Actual held control outside usable region rejected");Sizes();
  }
