   Check(game.Profile.CompletedJobs==0&&game.Profile.Cash==1130&&game.Profile.Level==2,"Isolated fresh company baseline");ReviewChecks();yield return Capture("home");Sizes();game.Hud.ShowPage(0);yield return null;Press("AcceptSelected");Check(!game.Paused&&game.ActiveJob!=null,"Actual tablet accepts selected service call");var gas=game.Vehicle.Accelerate;Held(gas,true);float startZ=game.Vehicle.transform.position.z;yield return new WaitForSecondsRealtime(2);Check(game.Vehicle.transform.position.z>startZ+8&&game.Vehicle.SpeedKmh>10,"Actual Rigidbody touch acceleration");game.Hud.ShowPage(0);yield return new WaitForFixedUpdate();Check(!gas.Held&&game.Vehicle.SpeedKmh<.01f,"Tablet stops actual van and clears held gas");var stop=game.Vehicle.transform.position;yield return new WaitForSecondsRealtime(.4f);Check(Vector3.Distance(stop,game.Vehicle.transform.position)<.01f,"Actual paused Rigidbody remains stationary");Sizes();ScrollRect scroll=null;foreach(var candidate in game.Hud.GetComponentsInChildren<ScrollRect>())if(candidate.name=="ScrollViewport")scroll=candidate;Check(scroll!=null&&scroll.viewport.GetComponent<Image>().raycastTarget,"Actual scroll viewport accepts touches");scroll.verticalNormalizedPosition=0;yield return null;Check(scroll.content.anchoredPosition.y>100,"Actual 24-call list scrolls to last row");yield return Capture("jobs-bottom");game.Hud.Close();
