   string[] ids={"faucet","switch","call-2-0","call-3-0"};for(int k=0;k<ids.Length;k++){if(k==1)Check(game.Transact(p=>RepairRules.BuyTool(p,1)),"Earned level unlocks actual voltage tool");if(k==2)Check(game.Transact(p=>RepairRules.BuyTool(p,2)),"Earned level unlocks actual professional kit");var job=JobCatalog.Find(ids[k]);Check(game.SelectJob(job),"Accept category "+job.CategoryIndex);game.ReturnToWorkshop();yield return new WaitForSecondsRealtime(.5f);gas=game.Vehicle.Accelerate;Held(gas,true);float until=Time.realtimeSinceStartup+45;while(Time.realtimeSinceStartup<until){float v=game.Vehicle.SpeedKmh/3.6f;float lead=v*v/(2*game.Vehicle.BrakeForce)+1;if(game.Vehicle.transform.position.z>=job.DestinationZ-lead)break;float target=Mathf.Atan2(job.DestinationX-game.Vehicle.transform.position.x,Mathf.Max(12,v))*Mathf.Rad2Deg;float turn=Mathf.DeltaAngle(game.Vehicle.transform.eulerAngles.y,target);SetHeld(game.Vehicle.Left,turn< -1);SetHeld(game.Vehicle.Right,turn>1);yield return new WaitForFixedUpdate();}SetHeld(game.Vehicle.Left,false);SetHeld(game.Vehicle.Right,false);Held(gas,false);Check(game.Vehicle.transform.position.z>=job.DestinationZ-12,"Drive actual route category "+job.CategoryIndex);var brake=game.Vehicle.Brake;Held(brake,true);until=Time.realtimeSinceStartup+4;while(game.Vehicle.SpeedKmh>1&&Time.realtimeSinceStartup<until)yield return new WaitForFixedUpdate();Held(brake,false);yield return new WaitForFixedUpdate();Debug.Log("REPAIR_QA_ARRIVAL "+job.Id+" pos="+game.Vehicle.transform.position+" speed="+game.Vehicle.SpeedKmh+" distance="+game.Distance);Check(game.BeginRepair(),"Stopped actual van enters category repair "+job.CategoryIndex);yield return null;int cash=game.Profile.Cash;long ticket=game.Profile.ActiveTicket;int completions=game.Profile.CompletedJobs;Check(!game.AdvanceRepair(2)&&game.Profile.RepairPhase==0,"Cannot skip first stage "+job.CategoryIndex);var hold=FindHold("RepairHold");Held(hold,true);yield return new WaitForSecondsRealtime(.3f);Held(hold,false);Check(game.Profile.RepairPhase==0,"Partial hold grants no phase "+job.CategoryIndex);Held(hold,true);until=Time.realtimeSinceStartup+3;while(game.Profile.RepairPhase==0&&Time.realtimeSinceStartup<until)yield return null;Check(game.Profile.RepairPhase==1,"Actual hold completes isolation "+job.CategoryIndex);yield return null;Press("RepairTap2");Check(game.Interaction.Taps==0,"Out of order contact resets "+job.CategoryIndex);for(int tap=0;tap<4;tap++){Press("RepairTap"+tap);yield return null;}Check(game.Profile.RepairPhase==2,"Actual four touch contacts persist phase "+job.CategoryIndex);yield return Capture("repair-category-"+job.CategoryIndex);hold=FindHold("RepairHold");Held(hold,true);until=Time.realtimeSinceStartup+3;while(game.RepairOpen&&Time.realtimeSinceStartup<until)yield return null;Check(!game.RepairOpen&&game.Profile.CompletedJobs==completions+1&&game.Profile.CompletedTicket==ticket&&game.Profile.Cash==cash+job.Reward,"Actual tested repair pays once "+job.CategoryIndex);Check(!game.AdvanceRepair(2)&&game.Profile.Cash==cash+job.Reward,"Paid repair rejects duplicate callback "+job.CategoryIndex);Check(!game.SelectJob(job)&&game.Profile.Cash==cash+job.Reward,"Paid contract cannot be spammed at customer "+job.CategoryIndex);var reloaded=JsonUtility.FromJson<RepairProfile>(JsonUtility.ToJson(game.Profile));Check(RepairRules.BeginJob(reloaded,job.Id)==0,"Paid contract guard survives actual JSON reload "+job.CategoryIndex);Check(game.ActiveJob==null&&!GameObject.Find("Distance"),"No false active-job distance after payment "+job.CategoryIndex);Check(Mathf.Abs(game.Vehicle.transform.position.z-job.DestinationZ)<6,"Completed repair remains at customer "+job.CategoryIndex);}
