   if(mode=="soak"){double begin=Time.realtimeSinceStartupAsDouble;long memory=UnityEngine.Profiling.Profiler.GetTotalAllocatedMemoryLong(),peak=memory;int capture=0;game.ReturnToWorkshop();SetHeld(game.Vehicle.Accelerate,true);bool stopping=false;int laps=0;while(Time.realtimeSinceStartupAsDouble-begin<1800){if(game.Vehicle.transform.position.z>410&&!stopping){SetHeld(game.Vehicle.Accelerate,false);SetHeld(game.Vehicle.Brake,true);stopping=true;}if(stopping&&game.Vehicle.SpeedKmh<1){SetHeld(game.Vehicle.Brake,false);game.ReturnToWorkshop();SetHeld(game.Vehicle.Accelerate,true);stopping=false;laps++;}float turn=Mathf.DeltaAngle(game.Vehicle.transform.eulerAngles.y,Mathf.Atan2(-game.Vehicle.transform.position.x,18)*Mathf.Rad2Deg);SetHeld(game.Vehicle.Left,turn< -1);SetHeld(game.Vehicle.Right,turn>1);frames.Add(Time.unscaledDeltaTime*1000);peak=Math.Max(peak,UnityEngine.Profiling.Profiler.GetTotalAllocatedMemoryLong());if(Time.realtimeSinceStartupAsDouble-begin>=capture*60){yield return Capture("soak-"+capture++);}yield return null;}game.Vehicle.ResetMotion();Check(laps>20,"Real soak includes repeated actual driving laps "+laps);game.Save();frames.Sort();File.WriteAllText(Path.Combine(output,"soak.json"),"{\"elapsedSeconds\":"+(Time.realtimeSinceStartupAsDouble-begin).ToString(System.Globalization.CultureInfo.InvariantCulture)+",\"frames\":"+frames.Count+",\"p95ms\":"+frames[(int)(frames.Count*.95)].ToString(System.Globalization.CultureInfo.InvariantCulture)+",\"startMemory\":"+memory+",\"endMemory\":"+UnityEngine.Profiling.Profiler.GetTotalAllocatedMemoryLong()+",\"peakMemory\":"+peak+",\"errors\":"+errors+"}");Check(errors==0,"Real 1800 second soak has no errors");}Finish();}
